mapper.select:
SELECT id, user_id, memory_type, memory_key, content, importance,
       source_conversation_id, expires_at, last_used_at, hit_count, created_at, updated_at
FROM ai_user_memory
WHERE user_id = #{userId}
  AND importance >= #{minImportance}
  AND (expires_at IS NULL OR expires_at > now())
ORDER BY importance DESC, updated_at DESC
LIMIT #{limit}

SELECT id, user_id, memory_type, memory_key, content, importance,
       source_conversation_id, expires_at, last_used_at, hit_count, created_at, updated_at
FROM ai_user_memory
WHERE user_id = #{userId}
ORDER BY updated_at DESC
LIMIT #{limit}

SELECT id, user_id, memory_type, memory_key, content, importance,
       source_conversation_id, expires_at, last_used_at, hit_count, created_at, updated_at
FROM ai_user_memory
WHERE user_id = #{userId}
  AND memory_type = #{memoryType}
  AND memory_key = #{memoryKey}

mapper.delete:
DELETE FROM ai_user_memory
WHERE id = #{id}
  AND user_id = #{userId}

mapper.update:
